(s/'pl/aridlin/kukirin/PauseUiCheck.java').write_text('''package pl.aridlin.kukirin;import java.util.*;import net.minecraft.client.Minecraft;import net.neoforged.neoforge.network.PacketDistributor;public class PauseUiCheck{static int checks;static void check(boolean b,String label){checks++;if(!b)throw new AssertionError(label);}public static void main(String[]args){Minecraft m=Minecraft.getInstance();var library=new ScooterMusicMenu.Catalog(List.of("one.wav","two.wav"),true,false,true,false);ScooterMusicScreen picker=new ScooterMusicScreen(library);m.setScreen(picker);check(picker.pauseButton.message.text().equals("Pause"),"new catalog starts with Pause");picker.pauseButton.action.accept(picker.pauseButton);check(!picker.pauseButton.active&&!picker.paused,"request awaits server rather than inventing local state");check(((ScooterMusicMenu.Request)PacketDistributor.sent.getLast()).action().equals("pause"),"pause request correctly routed");picker.search.setValue("one");picker.favoritesOnly=true;ScooterMusicFavorites.saved.add("one.wav");ScooterMusicClient.receive(new ScooterMusicMenu.Options(true,true,true),Runnable::run);check(picker.paused&&picker.pauseButton.active&&picker.pauseButton.message.text().equals("Resume"),"server acknowledgment changes to Resume");check(picker.searchTerm.equals("one")&&picker.favoritesOnly&&picker.autoplay&&picker.shuffle,"pause preserves search favorites and modes");picker.pauseButton.action.accept(picker.pauseButton);check(((ScooterMusicMenu.Request)PacketDistributor.sent.getLast()).action().equals("resume"),"resume request correctly routed");ScooterMusicClient.receive(new ScooterMusicMenu.Options(true,true,false),Runnable::run);check(!picker.paused&&picker.pauseButton.message.text().equals("Pause"),"resume acknowledgment switches label");YouTubeMusicScreen importScreen=new YouTubeMusicScreen(picker);m.setScreen(importScreen);ScooterMusicClient.receive(new ScooterMusicMenu.Options(true,true,true),Runnable::run);check(picker.paused&&picker.pauseButton.message.text().equals("Resume"),"acknowledgment reaches back library while importing");importScreen.onClose();check(m.screen==picker,"back retains source context");ScooterMusicClient.receive(new ScooterMusicMenu.CatalogPart(UUID.randomUUID(),0,true,false,true,false,true,true,"",List.of("one.wav","two.wav")),Runnable::run);check(picker.paused&&picker.catalog.paused(),"chunked catalog preserves server pause flag");picker.updateCatalog(new ScooterMusicMenu.Catalog(List.of("one.wav"),false,true,true,true),false);check(!picker.pauseButton.active&&picker.paused,"unsupported source cannot invoke pause");ScooterMusicScreen reopened=new ScooterMusicScreen(new ScooterMusicMenu.Catalog(List.of("one.wav"),true,false,true,true));m.setScreen(reopened);check(reopened.pauseButton.message.text().equals("Resume"),"reopening paused source starts Resume");ScooterMusicClient.receive(new ScooterMusicMenu.Options(true,false,true,40),Runnable::run);check(reopened.volumeSlider.message.text().equals("Volume: 40%"),"server gain label");int sentBefore=PacketDistributor.sent.size();reopened.volumeSlider.onClick(.37,0);check(PacketDistributor.sent.size()==sentBefore,"drag does not spam server");ScooterMusicClient.receive(new ScooterMusicMenu.Options(true,false,true,60),Runnable::run);check(reopened.volumeSlider.message.text().equals("Volume: 37%"),"incoming snapshot does not fight drag");reopened.volumeSlider.onRelease(.37,0);var volumeRequest=(ScooterMusicMenu.Request)PacketDistributor.sent.getLast();check(volumeRequest.action().equals("volume")&&volumeRequest.song().equals("37"),"release sends exact shared percentage");ScooterMusicClient.receive(new ScooterMusicMenu.Options(true,false,true,37),Runnable::run);check(reopened.volume==37&&reopened.paused&&reopened.pauseButton.message.text().equals("Resume"),"volume acknowledgment preserves pause");reopened.volumeSlider.onClick(0,0);reopened.volumeSlider.onRelease(0,0);check(((ScooterMusicMenu.Request)PacketDistributor.sent.getLast()).song().equals("0"),"slider reaches zero mute");reopened.volumeSlider.onClick(1,0);reopened.volumeSlider.onRelease(1,0);check(((ScooterMusicMenu.Request)PacketDistributor.sent.getLast()).song().equals("100"),"slider reaches full volume");System.out.println("{\\"success\\":true,\\"assertions\\":"+checks+",\\"authored_ui_sources_with_doubles\\":true,\\"native_game_launched\\":false}");}}''')
